def main():
    out, n = [], {}
    for week, area, typ, stem, opts, ans, expl, links in Q:
        n[week] = n.get(week, 0) + 1
        qid = f"{'ai' if week == 'ai' else 'w' + str(week)}-q{n[week]:02d}"
        q = {"id": qid, "week": week, "set": "weekly", "area": area, "type": typ, "stem": stem, "options": opts,
             "answer": ans, "explanation": expl, "learn": [{"label": L[k][0], "href": L[k][1]} for k in links]}
        if typ == "multi":
            q["choose"] = len(ans)
        out.append(q)
    p = Path(__file__).resolve().parent / "weekly-1-7-ai.json"
    p.write_text(json.dumps({"questions": out}, indent=1, ensure_ascii=True) + "\n")
    print(f"wrote {len(out)} questions: {n}")


if __name__ == "__main__":
    main()
